 function renderShop(){const list=$('upgrade-list');list.innerHTML='';upgrades.forEach(u=>{const amount=state.owned[u.id]||0,price=cost(u),button=document.createElement('button');button.className='upgrade';button.disabled=state.tokens<price;button.setAttribute('aria-label',`Buy ${u.name} for ${fmt(price)} tokens`);button.innerHTML=`<span class="upgrade-icon">${u.icon}</span><span><span class="upgrade-name">${u.name}<span class="owned">${amount}</span></span><span class="upgrade-desc">${u.desc}</span></span><span class="upgrade-buy"><span class="price">🪙 ${fmt(price)}</span><span class="rate">+${u.rate}/sec</span></span>`;button.addEventListener('click',()=>buy(u));list.appendChild(button)})}
