 function add(n){state.tokens+=n;state.total+=n;render()}
 function clickCoin(e){const power=clickPower();state.clicks++;add(power);const rect=$('coin-zone').getBoundingClientRect();const pop=document.createElement('span');pop.className='click-pop';pop.textContent='+'+fmt(power)+' 🪙';pop.style.left=(e.clientX?e.clientX-rect.left:rect.width/2)+'px';pop.style.top=(e.clientY?e.clientY-rect.top:rect.height/2)+'px';$('coin-zone').appendChild(pop);setTimeout(()=>pop.remove(),900);const coin=$('coin');coin.classList.remove('bump');void coin.offsetWidth;coin.classList.add('bump');setTimeout(()=>coin.classList.remove('bump'),130);if(state.sound)playClick();render()}
