 function claim(){const m=missions[Math.min(state.mission,missions.length-1)];if(state.total<m.goal||state.missionClaimed)return;state.tokens+=m.reward;state.missionClaimed=true;toast(`Mission complete! +${fmt(m.reward)} tokens`);if(state.mission<missions.length-1){state.mission++;state.missionClaimed=false}render();save()}
